namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();
    private readonly List<Notification> _notifications = [];

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(
        [
            CreateNotification("Welcome to the app!"),
            CreateNotification("Your profile was created."),
            CreateNotification("You have a new follower."),
        ]);
    }

    /// <summary>Returns all notifications available at this moment.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications];
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    /// <summary>
    /// Simulates external activity by occasionally adding a new notification.
    /// Called internally by the background polling to keep the demo interesting.
    /// </summary>
    public void SimulateActivity()
    {
        // ~30 % chance each tick to add a new notification.
        if (Random.Shared.Next(0, 10) < 3)
        {
            lock (_lock)
            {
                _notifications.Add(CreateNotification($"New event at {DateTime.Now:T}"));
            }
        }
    }

    private Notification CreateNotification(string message) =>
        new(_nextId++, message, DateTime.Now);
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-center">
                @n.Message
                <small class="text-muted">@n.Timestamp.ToString("T")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationsApp.Services.Notification> _notifications = [];
    private CancellationTokenSource? _cts;
    private int _latestId;

    // Runs during both prerender AND interactive init.
    // On prerender it populates _notifications for the SSR HTML.
    // On interactive init the same data is already serialized via
    // persistent component state, so we skip the service call.
    protected override void OnInitialized()
    {
        _notifications = NotificationService.GetAll();
        _latestId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;
    }

    // Only fires once the circuit is live (interactive). Never during prerender.
    protected override Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }

        return Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (TaskCanceledException)
            {
                return;
            }

            // Simulate external changes so the demo has something to show.
            NotificationService.SimulateActivity();

            var newer = NotificationService.GetSince(_latestId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                _latestId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

